        if (!part.isEmpty()) {
            parts.add(part);
        }
    }
    // Determine if path ends with slash
    boolean pathEndsWithSlash = path.endsWith("/");
    // If path does not end with slash and parts not empty, drop last part
    if (!pathEndsWithSlash && !parts.isEmpty()) {
        parts.remove(parts.size() - 1);
    }
    // Process relativePath components
    for (String comp : relativePath.split("/")) {
        if (comp.isEmpty() || comp.equals(".")) {
            continue;
        } else if (comp.equals("..")) {
            if (!parts.isEmpty()) {
                parts.remove(parts.size() - 1);
            }
        } else {
            parts.add(comp);
        }
    }
    // Build result
    StringBuilder sb = new StringBuilder();
    if (isAbsolute) {
        sb.append("/");
    }
    for (int i = 0; i < parts.size(); i++) {
        if (i > 0) sb.append("/");
        sb.append(parts.get(i));
    }
    // If result is empty and isAbsolute, return "/"
    if (sb.length() == 0 && isAbsolute) {
        return "/";
    }
    return sb.toString();
}

